#!/usr/bin/env python3
# Blackout-Radar Schritt 4: Schalter, Popup, Heroldsberg/Schnaittach.
# Basis sind die Pi-Dateien nach Schritt 3 inklusive der vier Handkorrekturen.
# Kein pip, kein apt, kein Mesh, keine Abschaltungs-Aenderung. Pinneberg bleibt pausiert.
from __future__ import annotations
import base64, hashlib, json, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
PATCH = ("dashboard.py", "blackout_radar.py", "lage_pages.py")
CHECK = ("pushover_push.py", "blackout_radar_targets.json")
NEU = "static/bor-kontur.json"
STAMP = "blackout_radar.bor4-import"
PI = {
    "dashboard.py": ("7ced5ca416b2e26a", 1391197),
    "blackout_radar.py": ("7715ba6de29ef277", 54156),
    "lage_pages.py": ("517c5d20ccf06d45", 222870),
    "pushover_push.py": ("2267a556ab7bb27f", 12129),
}

def load():
    raw = PAYLOAD_JSON
    paare = {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in raw["pairs"][name]] for name in PATCH}
    neu = base64.b64decode(raw["neu"][NEU])
    return paare, neu

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def pi_ok(name, data: bytes) -> bool:
    kopf, laenge = PI[name]
    if not sha(data).startswith(kopf) or len(data) != laenge:
        return False
    if name == "dashboard.py":
        return b"import traceback as _bor_tb" in data and b"/api/blackout/schalter" not in data and b"UG-DSL" in data
    if name == "blackout_radar.py":
        return b"not in (1, 2, 3, 4, 5)" in data and b"== len(rows) == 33" not in data and b"def schalten" not in data
    if name == "lage_pages.py":
        return b'id="borCard"' in data and b'id="borSwitch"' not in data and b"?'\\\\n'" in data
    if name == "pushover_push.py":
        return b"radar_1_rot" in data and b"def priority_for" in data
    return True

def struktur(data: bytes):
    try:
        doc = json.loads(data.decode("utf-8"))
    except (UnicodeError, ValueError):
        return False
    ziele = doc.get("targets")
    return doc.get("marker") == "blackoutRadar1" and isinstance(ziele, list) and isinstance(doc.get("uplink"), list) and len(ziele) > 0

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin Minute %02d" % m

def schreiben(path: Path, data: bytes):
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    tmp = path.with_name("." + path.name + ".tmp-bor4")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def sichern(path: Path, data: bytes):
    if not path.exists():
        return
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-bor4-*"))
    bak = path.with_name(path.name + ".bak-bor4-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def verwandle(data, pairs):
    if all(data.count(neu) == 1 and data.count(old) == 0 for old, neu in pairs):
        return data
    neu_data = data
    for old, neu in pairs:
        if neu_data.count(neu) == 1 and neu_data.count(old) == 0:
            continue
        if neu_data.count(old) != 1 or neu_data.count(neu) != 0:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu_data

def importieren(ordner: Path) -> int:
    ziel = ordner / "blackout_radar_targets.json"
    sichern(ziel, ziel.read_bytes())
    rc = __import__("subprocess").run([sys.executable, str(ordner / "blackout_radar.py"), "--neu-import"], cwd=str(ordner))
    if rc.returncode != 0:
        print("STOP: Import fehlgeschlagen. Dateien bleiben. Erneut: python3 blackout_radar.py --neu-import")
        return 2
    schreiben(ordner / STAMP, b"bor4\n")
    print("Import einmalig gelaufen. Kein woechentlicher Refresh. Naechster Start macht einen Vollscan.")
    return 0

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    paare, kontur = load()
    namen = list(PATCH) + list(CHECK)
    for name in namen:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
    blobs = {name: (ordner / name).read_bytes() for name in namen}
    for name in namen:
        print("%s sha16 %s bytes %d" % (name, sha(blobs[name])[:16], len(blobs[name])))
    if not struktur(blobs["blackout_radar_targets.json"]):
        print("STOP: targets.json Struktur")
        return 2
    print("targets.json nur Struktur, Hash %s bytes %d nicht gebunden" % (sha(blobs["blackout_radar_targets.json"])[:16], len(blobs["blackout_radar_targets.json"])))
    try:
        ziel = {name: verwandle(blobs[name], paare[name]) for name in PATCH}
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    kpfad = ordner / NEU
    vorhanden = kpfad.read_bytes() if kpfad.is_file() and not kpfad.is_symlink() else None
    for name in PATCH:
        print("%s endstand sha16 %s bytes %d" % (name, sha(ziel[name])[:16], len(ziel[name])))
    print("static/bor-kontur.json bytes %d" % len(kontur))
    stamp = (ordner / STAMP).is_file()
    if all(blobs[name] == ziel[name] for name in PATCH) and vorhanden == kontur and stamp:
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    code_neu = any(blobs[name] != ziel[name] for name in PATCH) or vorhanden != kontur
    if code_neu:
        for name in ("dashboard.py", "blackout_radar.py", "lage_pages.py", "pushover_push.py"):
            if name in PATCH and ziel[name] == blobs[name]:
                continue
            if not pi_ok(name, blobs[name]):
                print("STOP: %s %s ist nicht die Basis" % (name, sha(blobs[name])[:16]))
                return 2
        if vorhanden not in (None, kontur):
            print("STOP: static/bor-kontur.json weicht ab")
            return 2
        if ziel["dashboard.py"].count(b"UG-DSL") != blobs["dashboard.py"].count(b"UG-DSL"):
            print("STOP: UG-DSL in dashboard.py")
            return 2
        if ziel["lage_pages.py"].count(b"UG-DSL") != blobs["lage_pages.py"].count(b"UG-DSL"):
            print("STOP: UG-DSL in lage_pages.py")
            return 2
        if b"import traceback as _bor_tb" not in ziel["dashboard.py"] or b"/api/blackout/schalter" not in ziel["dashboard.py"]:
            print("STOP: Schalter oder Traceback fehlt")
            return 2
        if b"not in (1, 2, 3, 4, 5)" not in ziel["blackout_radar.py"] or b"== len(rows) == 33" in ziel["blackout_radar.py"]:
            print("STOP: Handkorrektur in blackout_radar.py fehlt")
            return 2
        if b'id="borSwitch"' not in ziel["lage_pages.py"] or b"autoPan:false" not in ziel["lage_pages.py"] or b"clearLayers" in ziel["lage_pages.py"]:
            print("STOP: Kachel unvollstaendig")
            return 2
        for name in PATCH:
            try:
                compile(ziel[name], name, "exec")
            except SyntaxError as exc:
                print("STOP: Syntax %s %s" % (name, exc.lineno))
                return 2
    frei, meldung = fenster(jetzt)
    print(meldung)
    if not frei and not dry:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Import, kein Neustart")
        print("Befehl: python3 blackout_radar.py --neu-import")
        print("Pruefung: curl -sS http://127.0.0.1:5000/api/blackout/radar")
        return 0
    try:
        for name in PATCH:
            if blobs[name] == ziel[name]:
                continue
            sichern(ordner / name, blobs[name])
            schreiben(ordner / name, ziel[name])
        if vorhanden != kontur:
            if kpfad.exists():
                sichern(kpfad, vorhanden)
            schreiben(kpfad, kontur)
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    if not stamp:
        rc = importieren(ordner)
        if rc != 0:
            return rc
    print("geschrieben. Schalter, Popups, Heroldsberg und Schnaittach.")
    print("Pruefung: curl -sS http://127.0.0.1:5000/api/blackout/radar")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Datei ist neu, der Neustart bleibt in der Sperre aus.")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 13, 12, 12))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 45))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 0))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 4))[0]
    assert pi_ok("dashboard.py", b"import traceback as _bor_tb") is False
    assert struktur(b'{"marker":"blackoutRadar1","uplink":["1.1.1.1"],"targets":[{}]}')
    assert not struktur(b"{}")
    paare, _kontur = load()
    for name in PATCH:
        old, neu = paare[name][0]
        assert old != neu and neu.count(old) == 0
        assert verwandle(b"VOR" + old + b"NACH", paare[name]) == b"VOR" + neu + b"NACH"
        assert verwandle(b"VOR" + neu + b"NACH", paare[name]) == b"VOR" + neu + b"NACH"
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="bor4-apply-"))
    for name in list(PATCH) + list(CHECK):
        (ordner / name).write_bytes(b"UNBERUEHRT")
    vorher = {name: (ordner / name).read_bytes() for name in list(PATCH) + list(CHECK)}
    assert apply_dir(ordner, False, True, datetime(2026, 11, 13, 12, 12)) == 2
    assert {name: (ordner / name).read_bytes() for name in vorher} == vorher
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

if __name__ == "__main__":
    sys.exit(main(sys.argv))

PAYLOAD_JSON = {"pairs":{"dashboard.py":[{"old":"","new":""}],"blackout_radar.py":[{"old":"","new":""}],"lage_pages.py":[{"old":"","new":""}]},"neu":{"static/bor-kontur.json":""}}
